#!/usr/bin/env python3
"""Generate overlay_id_decode_gen.c for PBW2_N3DS pointer -> numeric overlay id."""

from __future__ import annotations

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OVERLAY_H = ROOT / "include" / "gfl" / "overlay.h"
OUT = ROOT / "n3ds" / "nitro" / "overlay_id_decode_gen.c"


def main() -> int:
    ids = sorted(int(m.group(1)) for m in re.finditer(r"extern u32 OVERLAY_(\d+)_ID", OVERLAY_H.read_text()))
    lines = [
        "/* SPDX-License-Identifier: GPL-3.0-or-later */",
        "/* Generated by scripts/n3ds_overlay_id_decode.py */",
        '#include "types.h"',
        '#include "gfl/overlay.h"',
        "",
        "u32 PbW2_NormalizeOverlayId(u32 overlayId) {",
        "    if (overlayId <= 0x3ffu) {",
        "        return overlayId;",
        "    }",
    ]
    for n in ids:
        lines.append(f"    if (overlayId == (u32)OVERLAY_{n}_ID) {{ return {n}; }}")
    lines += [
        "    return overlayId;",
        "}",
        "",
    ]
    OUT.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)} ({len(ids)} ids)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
